'use client'
/** Stepper: the MATRIX card `ui-stepper` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-stepper')!

export type MatrixStepperProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixStepper(props: MatrixStepperProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
